window.DEEPDIVE=window.DEEPDIVE||{};window.DEEPDIVE["reranking"]={"title":"重排 Reranking：在高召回候选中做精细相关性判断","subtitle":"理解双塔召回、交叉编码器、late interaction、LLM 重排和位置偏差，并设计 Recall@k 到端到端答案的评测。","thesis":"检索首阶段用可预计算表示快速召回，重排器对较小候选集进行更昂贵的查询—文档交互；它能提高前排精度，却<b>无法找回首阶段未召回的证据</b>。","quality":{"contractVersion":2,"examples":[{"section":7,"evidence":{"setup":"双塔 top-4","rule":"交叉编码器","steps":"从 rank=2 到 rank=1 得 0.5 到 1.0","interpretation":"只说明首个相关结果提前"}}],"formulas":[{"id":"reranking-mrr-change","section":7,"formulaIndex":1,"symbols":[{"name":"MRRbefore","meaning":"重排前首个相关结果的倒数排名","evidence":"输出 MRRbefore"},{"name":"rankbefore","meaning":"重排前首个相关结果名次","evidence":"从 rank=2"},{"name":"MRRafter","meaning":"重排后首个相关结果的倒数排名","evidence":"MRRafter"},{"name":"rankafter","meaning":"重排后首个相关结果名次","evidence":"到 rank=1"}]},{"id":"reranking-batched-latency","section":8,"formulaIndex":1,"symbols":[{"name":"Trerank","meaning":"候选重排总延迟","evidence":"输出重排延迟 Trerank"},{"name":"Tfixed","meaning":"网络与编排固定开销","evidence":"固定编排开销 Tfixed"},{"name":"Tbatch","meaning":"交叉编码器每批处理耗时","evidence":"每批耗时 Tbatch"},{"name":"k","meaning":"需要重排的候选总数","evidence":"候选数 k"},{"name":"b","meaning":"每个批次可处理的候选数","evidence":"每批候选量 b"}]}],"termReviews":[],"sectionContracts":[{"section":1,"definition":{"answer":"重排在高召回候选集合内做更精细的相关性排序。","evidence":"两阶段为何必要"},"problem":{"answer":"它避免让昂贵模型逐个比较数据库全部文档。","evidence":"为什么不让最强模型比较数据库全部文档"},"inputOutput":{"answer":"输入查询全库和预算，输出候选及重排前排片段。","evidence":"输出首阶段高召回候选及重排后的前排片段"},"mechanism":{"answer":"便宜首阶段缩小集合，昂贵重排器只重排该集合。","evidence":"只在该集合内做精细交互"},"interpretation":{"answer":"证据不在候选中是召回失败而不是排序失败。","evidence":"不是重排失败"},"boundary":{"answer":"只有小库且预算允许时才可能省略首阶段。","evidence":"才可能省略首阶段"}},{"section":2,"definition":{"answer":"双塔独立编码查询文档，交叉编码器共同编码二者。","evidence":"双塔与交叉编码器"},"problem":{"answer":"它解释交叉编码为何更精细同时计算更慢。","evidence":"重排器为何通常更准但更慢"},"inputOutput":{"answer":"输入查询文档和预算，输出双塔分或交叉相关分。","evidence":"输出双塔相似分或交叉编码相关分"},"mechanism":{"answer":"交叉编码让查询和文档 token 直接交互。","evidence":"共同读取查询与文档 token"},"interpretation":{"answer":"高分表示训练目标下相关，不代表来源真实。","evidence":"不证明来源真实"},"boundary":{"answer":"长文截断后的低分不能代表全文无关。","evidence":"低分不能代表全文无关"}},{"section":3,"definition":{"answer":"候选深度 k 是送入重排器的首阶段结果数量。","evidence":"候选深度的上限"},"problem":{"answer":"它权衡正确证据覆盖与线性增长的重排成本。","evidence":"重排 top-20 与 top-200 如何权衡"},"inputOutput":{"answer":"输入 Recall 曲线和预算，输出重排候选 k。","evidence":"输出需要重排的 k"},"mechanism":{"answer":"观察 Recall 随 k 增长并在收益饱和处控制深度。","evidence":"增大 k 提高包含正确证据的机会"},"interpretation":{"answer":"Recall 饱和后继续扩大会增加噪声和延迟。","evidence":"主要增加噪声和延迟"},"boundary":{"answer":"Recall 很低时应先修召回而非重排器。","evidence":"应先修召回而不是换更强重排器"}},{"section":4,"definition":{"answer":"Late interaction 用预计算 token 向量保留局部查询文档交互。","evidence":"Late interaction"},"problem":{"answer":"它在双塔速度与交叉编码精度之间寻找折中。","evidence":"能否保留 token 交互又预计算文档"},"inputOutput":{"answer":"输入 token 向量，输出 MaxSim 聚合相关分。","evidence":"输出通过 MaxSim 聚合的相关分"},"mechanism":{"answer":"离线存文档 token，在线逐查询 token 找最大匹配并聚合。","evidence":"在线仍保留查询 token 与文档 token 的局部匹配"},"interpretation":{"answer":"它比单向量保留更多局部匹配，同时索引更大。","evidence":"代价是索引更大"},"boundary":{"answer":"相关性分不能替代时效、权限和事实核验。","evidence":"不能替代时效、权限或事实核验"}},{"section":5,"definition":{"answer":"LLM 重排可用点式、成对或列表方式比较候选。","evidence":"LLM 重排的偏差"},"problem":{"answer":"它处理语言模型列表排序可能出现的位置和长度偏差。","evidence":"会出现什么问题"},"inputOutput":{"answer":"输入候选顺序和提示，输出点式成对或列表排序。","evidence":"输出点式、成对或列表排序"},"mechanism":{"answer":"用随机置换和成对校准检查排序对输入位置的敏感性。","evidence":"置换与成对校准用于测偏差"},"interpretation":{"answer":"只有不同置换下排序稳定才构成可信证据。","evidence":"排序变化稳定才是可信证据"},"boundary":{"answer":"成本高且位置偏差未校准时不适合默认全量使用。","evidence":"不适合作为高吞吐默认方案"}},{"section":6,"definition":{"answer":"重排端到端评测连接排序、证据、引用、成本和任务成功。","evidence":"端到端评测输入重排前后候选、必要证据"},"problem":{"answer":"它解释 NDCG 提升为何不一定使最终答案更好。","evidence":"NDCG 提升为何不一定让答案更好"},"inputOutput":{"answer":"输入候选证据引用任务，输出排序与任务指标。","evidence":"输出 NDCG、MRR、证据覆盖、引用忠实、延迟、费用和任务成功"},"mechanism":{"answer":"比较重排前后证据进入上下文及被正确引用的变化。","evidence":"输入重排前后候选、必要证据、引用和最终任务结果"},"interpretation":{"answer":"排序改善不代表生成器正确使用了证据。","evidence":"不说明生成器正确使用证据"},"boundary":{"answer":"版本权限和错误但贴题文档必须单独设门禁。","evidence":"必须包含版本、权限和答案切片"}},{"section":7,"definition":{"answer":"排序案例把质量例外从召回第三位提升到重排第一位。","evidence":"一次排序怎样改变可见证据"},"problem":{"answer":"它说明近似材料排前如何把最终答案带偏。","evidence":"为什么答案仍可能被排在前面的近似材料带偏"},"inputOutput":{"answer":"输入候选名次和等级，输出前后 MRR 与证据覆盖。","evidence":"输出 MRRbefore、MRRafter 与 top2 证据覆盖"},"mechanism":{"answer":"按首个相关结果名次取倒数并比较重排前后。","evidence":"MRR 是首个相关结果排名 rank 的倒数"},"interpretation":{"answer":"从零点五到一只说明首个相关结果被提前。","evidence":"只说明首个相关结果提前"},"boundary":{"answer":"来源时效和多证据使用仍需独立验证。","evidence":"旧版条款可信度和生成是否同时使用一般规则与例外仍需另测"}},{"section":8,"definition":{"answer":"重排延迟由固定开销和候选批次数共同构成。","evidence":"精度收益怎样换算成延迟预算"},"problem":{"answer":"它解释为何线上不能总把 top200 送交叉编码器。","evidence":"为什么线上系统不能总把 top-200 交给交叉编码器"},"inputOutput":{"answer":"输入批大小候选数和耗时，输出总重排延迟。","evidence":"输出重排延迟 Trerank"},"mechanism":{"answer":"候选数除批容量向上取整，再乘每批耗时并加固定开销。","evidence":"批次数是向上取整 k/b"},"interpretation":{"answer":"二十与一百条延迟只适用于给定硬件和批设置。","evidence":"只适用于给定硬件和批设置"},"boundary":{"answer":"额外 Recall 必须证明可改善最终任务才值得延迟。","evidence":"必须证明能改善最终任务"}}]},"html":"\n        <div class=\"dd-goals\"><b>读完你应该能：</b>区分召回与重排；解释 cross-encoder；选择候选深度；评测位置、延迟与答案贡献。</div>\n        \n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">1</span>两阶段为何必要<span class=\"dd-badge intuition\">直觉</span></h2><p class=\"dd-lead\">为什么不让最强模型比较数据库全部文档？</p><p>全库精细交互成本过高。向量/关键词先取高召回候选，再用更贵模型排序，形成速度与精度分工。</p><p>线上诊断要保存重排前后的候选 id、首阶段分数、重排分数、文档版本和最终引用。正确证据不在候选中是召回失败；在候选中却仍排后是排序失败；排进上下文但未被引用则属于装配或生成失败。三个现象需要不同修复，不能都归咎于重排模型。跨领域时绝对分数还可能整体漂移，因此固定阈值需按查询类型重新校准。</p><p>两阶段检索输入查询、全库和延迟预算，输出首阶段高召回候选及重排后的前排片段。首阶段用便宜表示缩小集合，重排器只在该集合内做精细交互；正确证据不在候选中属于召回失败，不是重排失败。全库规模小且可承受精细比较时才可能省略首阶段。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">2</span>双塔与交叉编码器<span class=\"dd-badge eng\">架构</span></h2><p class=\"dd-lead\">重排器为何通常更准但更慢？</p><p>双塔分别编码查询和文档，可预计算；交叉编码器把二者一起输入，让每个 token 交互，相关性更细但每个候选都需一次前向。</p><p>这种交互尤其有利于条件、数字、否定和实体关系，例如区分“质量问题不受 30 天限制”与“所有商品受 30 天限制”。但输入长度仍有限，长文档可能被截掉关键句；应按结构选择摘要、窗口或关键段，而不是把截断后的低分误解为全文不相关。</p><p>架构选择输入查询、候选文档、交互粒度和计算预算，输出双塔相似分或交叉编码相关分。双塔分别编码便于预计算，交叉编码器共同读取查询与文档 token，能识别条件、数字和否定却需逐候选计算；高分只表示训练目标下相关，不证明来源真实。长文档被截断时低分不能代表全文无关。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">3</span>候选深度的上限<span class=\"dd-badge math\">度量</span></h2><p class=\"dd-lead\">重排 top-20 与 top-200 如何权衡？</p><p>候选 k 大提高包含正确证据概率，也线性增加重排成本与噪声。若 Recall@k 已低，先修召回；重排最多重新排列已有集合。应按查询桶观察 Recall 曲线何处趋于饱和。</p><p>候选深度输入首阶段 Recall 曲线、重排单条成本和上下文预算，输出需要重排的 k。增大 k 提高包含正确证据的机会并近似线性增加计算；若 RecallK 已饱和，继续扩大会主要增加噪声和延迟。若 RecallK 很低，应先修召回而不是换更强重排器。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">4</span>Late interaction<span class=\"dd-badge intuition\">折中</span></h2><p class=\"dd-lead\">能否保留 token 交互又预计算文档？</p><p>ColBERT 为查询和文档保留 token 级向量，在线做 MaxSim 聚合，在双塔速度与交叉编码精度间折中，但索引更大。</p><p>Late interaction 输入查询与文档的 token 级向量，输出通过 MaxSim 聚合的相关分。文档 token 向量可离线预计算，在线仍保留查询 token 与文档 token 的局部匹配，因此介于双塔和交叉编码器之间；代价是索引更大。它仍只衡量相关性，不能替代时效、权限或事实核验。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">5</span>LLM 重排的偏差<span class=\"dd-badge eng\">LLM</span></h2><p class=\"dd-lead\">让 LLM 排列表会出现什么问题？</p><p>点式打分、成对比较和列表排序各有成本；列表模型可能有首因、长度和顺序偏差。随机置换、滑窗与成对校准可诊断，但调用成本高。</p><p>LLM 重排输入候选及其顺序、评分提示和比较方式，输出点式、成对或列表排序。列表模型可能偏爱靠前、较长或措辞显眼的候选，置换与成对校准用于测偏差；排序变化稳定才是可信证据。调用昂贵且位置偏差未校准时，不适合作为高吞吐默认方案。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">6</span>端到端评测<span class=\"dd-badge eng\">评测</span></h2><p class=\"dd-lead\">NDCG 提升为何不一定让答案更好？</p><p>还要检查关键证据是否进入上下文、引用忠实度与最终任务成功。按查询类型、文档长度和时效切片，同时报告 NDCG/MRR、延迟与费用。</p><div class=\"dd-note warn\"><b>相关不等于可信。</b>　重排器可能把更贴题但错误的文档排前。</div><p>端到端评测输入重排前后候选、必要证据、引用和最终任务结果，输出 NDCG、MRR、证据覆盖、引用忠实、延迟、费用和任务成功。排序指标提高只说明相关标注下顺序改善，不说明生成器正确使用证据；错误但贴题的文档仍可能被排前。上线门禁必须包含版本、权限和答案切片。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">7</span>一次排序怎样改变可见证据<span class=\"dd-badge math\">运行示例</span></h2><p class=\"dd-lead\">首阶段已经召回正确材料，为什么答案仍可能被排在前面的近似材料带偏？</p><figure class=\"dd-fig\"><svg viewBox=\"0 0 680 225\" role=\"img\" aria-label=\"双塔召回候选经交叉编码器重排后把质量例外提到首位\"><defs><marker id=\"rr1\" markerWidth=\"8\" markerHeight=\"8\" refX=\"6\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 z\" fill=\"#6b7484\"/></marker></defs><rect x=\"18\" y=\"35\" width=\"155\" height=\"155\" rx=\"8\" fill=\"#21252d\" stroke=\"#6b8cbe\"/><text x=\"95\" y=\"58\" text-anchor=\"middle\" class=\"svg-t\">双塔 top-4</text><text x=\"36\" y=\"84\" class=\"svg-t\" font-size=\"10\">1. 到账时间　0.84</text><text x=\"36\" y=\"108\" class=\"svg-t\" font-size=\"10\">2. 一般期限　0.82</text><text x=\"36\" y=\"132\" class=\"svg-t\" font-size=\"10\">3. 质量例外　0.79</text><text x=\"36\" y=\"156\" class=\"svg-t\" font-size=\"10\">4. 旧版条款　0.77</text><path d=\"M173,112 L252,112\" stroke=\"#6b7484\" marker-end=\"url(#rr1)\"/><rect x=\"254\" y=\"54\" width=\"164\" height=\"116\" rx=\"8\" fill=\"#21252d\" stroke=\"#d3a05a\"/><text x=\"336\" y=\"78\" text-anchor=\"middle\" class=\"svg-t\">交叉编码器</text><text x=\"336\" y=\"102\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"10\">[查询；候选] 共同编码</text><text x=\"336\" y=\"123\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"10\">token 级条件/否定交互</text><text x=\"336\" y=\"144\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"10\">每个候选一次前向</text><path d=\"M418,112 L497,112\" stroke=\"#6b7484\" marker-end=\"url(#rr1)\"/><rect x=\"499\" y=\"35\" width=\"163\" height=\"155\" rx=\"8\" fill=\"#21252d\" stroke=\"#4f9d78\"/><text x=\"580\" y=\"58\" text-anchor=\"middle\" class=\"svg-t\">重排后 top-3</text><text x=\"517\" y=\"84\" class=\"svg-t\" font-size=\"10\">1. 质量例外　0.93</text><text x=\"517\" y=\"108\" class=\"svg-t\" font-size=\"10\">2. 一般期限　0.88</text><text x=\"517\" y=\"132\" class=\"svg-t\" font-size=\"10\">3. 旧版条款　0.41</text><text x=\"517\" y=\"161\" class=\"svg-t\" font-size=\"10\">到账时间降至第 4</text><text x=\"340\" y=\"213\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"10\">重排只改变已有集合的顺序；如果质量例外不在左侧候选中，右侧永远不会出现它</text></svg><figcaption>图 1　双塔把查询和文档压成独立摘要，交叉编码器则让“35 天”“质量问题”“不受期限限制”等 token 直接互动，因此能修正细粒度条件排序。</figcaption></figure><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>候选</th><th>人工相关等级</th><th>召回名次</th><th>重排名次</th><th>为何改变</th></tr></thead><tbody><tr><td>质量问题例外</td><td>3（直接回答）</td><td>3</td><td>1</td><td>同时匹配“质量问题”和期限例外</td></tr><tr><td>30 天一般规则</td><td>2（必要背景）</td><td>2</td><td>2</td><td>说明默认规则但不是完整答案</td></tr><tr><td>旧版质量条款</td><td>1（相关但过期）</td><td>4</td><td>3</td><td>文本相关，仍需独立时效过滤</td></tr><tr><td>退款到账时间</td><td>0（不回答资格）</td><td>1</td><td>4</td><td>共享“退款”主题但任务意图不同</td></tr></tbody></table></div><p>首个相关结果的倒数名次 MRR 从 <code>1/2=0.5</code>（若把等级≥2视为相关）提升为 <code>1/1=1.0</code>。但这个数字没有证明旧版条款可信，也没有证明生成器会同时使用一般规则和例外；因此还要测 top-2 证据覆盖、版本过滤、引用忠实和最终答案。</p><div class=\"dd-note key\"><b>集合上限：</b>若首阶段 top-4 不包含质量例外，候选 Recall@4=0，任何重排模型的最好结果仍是 0。先画 Recall@k 曲线确定证据通常在哪个深度出现，再决定重排 k。</div><p>排序案例输入四个候选的召回名次、人工相关等级和重排名次，输出 MRRbefore、MRRafter 与 top2 证据覆盖。MRR 是首个相关结果排名 rank 的倒数；从 rank=2 到 rank=1 得 0.5 到 1.0，只说明首个相关结果提前。旧版条款可信度和生成是否同时使用一般规则与例外仍需另测。</p><div class=\"dd-formula\"><math display=\"block\" aria-label=\"重排前后首个相关结果的倒数排名\"><mi>MRRbefore</mi><mo>=</mo><mfrac><mn>1</mn><mi>rankbefore</mi></mfrac><mo>=</mo><mfrac><mn>1</mn><mn>2</mn></mfrac><mo>=</mo><mn>0.5</mn><mo>;</mo><mi>MRRafter</mi><mo>=</mo><mfrac><mn>1</mn><mi>rankafter</mi></mfrac><mo>=</mo><mn>1.0</mn></math></div></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">8</span>精度收益怎样换算成延迟预算<span class=\"dd-badge math\">成本边界</span></h2><p class=\"dd-lead\">候选越多越保险，但为什么线上系统不能总把 top-200 交给交叉编码器？</p><p>假设交叉编码器批量处理 20 对查询—文档需要 35 ms，固定网络与编排开销 25 ms：重排 20 条约 <code>25+35=60 ms</code>；重排 100 条需 5 批，约 <code>25+5×35=200 ms</code>。若 Recall@20=92%、Recall@100=96%，额外 140 ms 只换 4 个百分点的候选覆盖，还未必转化为答案提升。</p><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>候选深度</th><th>证据 Recall</th><th>估算重排延迟</th><th>适用判断</th></tr></thead><tbody><tr><td>20</td><td>92%</td><td>60 ms</td><td>默认交互场景</td></tr><tr><td>50</td><td>95%</td><td>约 130 ms</td><td>高价值且召回尾部仍有收益</td></tr><tr><td>100</td><td>96%</td><td>200 ms</td><td>需证明额外 1% 能改善任务</td></tr><tr><td>200</td><td>96.2%</td><td>约 375 ms</td><td>收益已饱和，通常应修首阶段</td></tr></tbody></table></div><p>生产调参应先设端到端延迟 SLO，再给召回、重排和生成分配预算。可按查询难度自适应：精确编号查询靠关键词即可少排，歧义自然语言查询扩大候选；高风险问题在版本和权威性过滤后再精排。批处理会降低单位成本，但不能消除候选数增加带来的总计算。</p><div class=\"dd-note warn\"><b>失败边界：</b>交叉编码器学习的是标注相关性。如果训练集把“更像问题”误当成“能支撑答案”，它会稳定地把措辞贴近但缺少条件的片段排前；对新领域、长文档、否定和时间敏感查询必须单独切片评测。</div><p>延迟预算案例输入固定编排开销 Tfixed、每批耗时 Tbatch、每批候选量 b 和候选数 k，输出重排延迟 Trerank。批次数是向上取整 k/b，故 Trerank=Tfixed+ceil(k/b)×Tbatch；20 条约 60ms，100 条约 200ms。估算只适用于给定硬件和批设置，额外 Recall 必须证明能改善最终任务。</p><div class=\"dd-formula\"><math display=\"block\" aria-label=\"分批交叉编码重排延迟\"><mi>Trerank</mi><mo>=</mo><mi>Tfixed</mi><mo>+</mo><mo>⌈</mo><mfrac><mi>k</mi><mi>b</mi></mfrac><mo>⌉</mo><mo>×</mo><mi>Tbatch</mi></math></div></section>\n      <section class=\"dd-sec\" data-section-role=\"reference\"><h2><span class=\"dd-n\">9</span>常见误区与学习路线<span class=\"dd-badge intuition\">误区与路线</span></h2><p class=\"dd-lead\">重排是候选集上的精细判断器，不是召回器、事实核验器或权限系统。</p><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>常见误解</th><th>更准确的理解</th></tr></thead><tbody><tr><td>重排器能修复所有检索问题</td><td>它只能排列首阶段已有候选，无法找回集合外证据</td></tr><tr><td>cross-encoder 分数可当事实置信度</td><td>分数表示训练目标下的相关性，不证明来源真实、最新或有权限</td></tr><tr><td>候选 k 越大，答案必然越好</td><td>Recall 会饱和，而延迟、费用和噪声持续增加</td></tr><tr><td>NDCG 提升就可上线</td><td>还需验证证据覆盖、引用忠实、答案成功和各类查询切片</td></tr><tr><td>LLM 列表排序天然理解全局</td><td>它可能受输入顺序、长度和位置偏差影响，要置换与校准</td></tr></tbody></table></div><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>层级</th><th>概念依赖与延伸</th></tr></thead><tbody><tr><td>先修</td><td>嵌入、检索、注意力、向量数据库</td></tr><tr><td><b>本页核心</b></td><td>双塔召回、交叉编码、候选深度、MRR/NDCG 与延迟预算</td></tr><tr><td>紧邻</td><td>RAG、中间迷失、上下文工程、切块</td></tr><tr><td>工程延伸</td><td>高级 RAG、评测、模型路由、缓存与可观测性</td></tr></tbody></table></div></section>\n        <section class=\"dd-sec\" data-section-role=\"synthesis\"><h2><span class=\"dd-n\">10</span>把因果链连起来<span class=\"dd-badge intuition\">综合</span></h2><p class=\"dd-lead\">这个概念怎样从问题一路连接到可验证的实践？</p><ol class=\"dd-chain\"><li>首阶段快速召回候选</li><li>检查正确证据 Recall@k</li><li>重排器做精细交互</li><li>截取前若干进入上下文</li><li>生成器引用并回答</li><li>用检索与答案指标共同回归</li></ol></section>\n        <section class=\"dd-sec\" data-section-role=\"assessment\"><h2><span class=\"dd-n\">11</span>误区与自测<span class=\"dd-badge intuition\">自测</span></h2><p class=\"dd-lead\">你能否不用背术语，解释它的机制、边界与验证方法？</p><div class=\"dd-quiz\"><ol><li>重排能找回未召回文档吗？</li><li>cross-encoder 为何更慢？</li><li>k 增大的代价？</li><li>ColBERT 的折中？</li><li>为何还测最终答案？</li><li>假设“重排 Reranking：在高召回候选中做精细相关性判断”在离线示例上表现正常、上线后核心结果却下降，你会怎样按输入、内部变换、输出反馈和适用边界定位问题？</li><li>如何为“重排 Reranking：在高召回候选中做精细相关性判断”设计一个最小对照实验，证明观察到的改善来自核心机制，而不是数据、提示、权限或评测口径同时变化？</li><li>为什么不能只用一个平均分判断“重排 Reranking：在高召回候选中做精细相关性判断”已经可靠？应怎样按场景切片并设置失败边界？</li></ol></div><details class=\"dd-answers\"><summary>参考答案</summary><ol><li>不能。</li><li>查询与每个文档共同编码。</li><li>重排计算和噪声增加。</li><li>预计算 token 向量并在线 late interaction。</li><li>排序指标提升不保证证据被正确使用。</li><li>先保存同一失败样本及环境，确认输入、权限和前置条件没有漂移；再记录关键中间状态，检查机制是否按本页描述完成变换；随后把原始输出与独立指标、人工终验对照；最后用边界样例和对照实验复测。只有定位到首次偏离预期的环节，才能判断应修改数据、机制、评测还是使用边界。</li><li>固定数据、模型版本、提示、权限、预算和评测，只改变一个与核心机制直接相关的因素，并在多个样本与随机种子上重复；同时保存中间状态和失败样本。若差异只在目标因素变化时稳定出现，才支持机制解释，否则应继续排查混杂变量。</li><li>平均分会隐藏少数类别、极端输入、成本、延迟和安全失败。至少按难度、输入类型、长度或规模、风险等级及已知边界切片，同时报告质量、资源和失败率；高风险硬约束不能被其他切片的高分抵消。</li></ol></details></section>\n        <div class=\"dd-src\"><b>资料来源与改编说明</b><ul><li><a href=\"https://arxiv.org/abs/1908.10084\" target=\"_blank\" rel=\"noopener\">Sentence-BERT</a>：双塔与交叉编码比较</li><li><a href=\"https://arxiv.org/abs/2004.12832\" target=\"_blank\" rel=\"noopener\">ColBERT</a>：late interaction</li><li><a href=\"https://arxiv.org/abs/2304.09542\" target=\"_blank\" rel=\"noopener\">Is ChatGPT Good at Search? RankGPT</a>：LLM 列表重排</li></ul><div class=\"dd-src-date\">访问日期：2026-07-22</div></div>"};
